    ,keyboard: '<rect x="3" y="6" width="18" height="12" rx="2"/><path d="M7 10h.01M11 10h.01M15 10h.01M18 10h.01M7 14h.01M10 14h7"/>'
    ,clock: '<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'
